    "    const gw = Math.max(1, step * 0.78), bw = Math.max(1, gw / groups - (groups > 1 \077 2 : 0));\n"
    "    for (let i = 0; i < n; i++) {\n"
    "      let base = 0;\n"
    "      series.forEach((s, k) => {\n"
    "        const x = s.values[i] || 0; if (!x) return;\n"
    "        const h = ph * x / max;\n"
    "        const bx = L + step * i + (step - gw) / 2 + (kind === \042bar\042 \077 k * (gw / groups) : 0);\n"
    "        const by = kind === \042stack\042 \077 T + ph - ph * (base + x) / max : T + ph - h;\n"
    "        const r = Math.min(4, bw / 2, h);\n"
    "        const top = kind !== \042stack\042 || k === series.length - 1 || !series.slice(k + 1).some(o => o.values[i]);\n"
    "        /* rounded on top only, anchored to the baseline; a 2px gap between stacked segments */\n"
    "        const hh = kind === \042stack\042 && base > 0 \077 h - 2 : h;\n"
    "        const path = top\n"
    "          \077 `M${bx} ${by + hh}V${by + r}Q${bx} ${by} ${bx + r} ${by}H${bx + bw - r}Q${bx + bw} ${by} ${bx + bw} ${by + r}V${by + hh}Z`\n"
    "          : `M${bx} ${by + hh}V${by}H${bx + bw}V${by + hh}Z`;\n"
    "        el(\042path\042, {d: path, fill: s.color, opacity: opts.partial && opts.partial(i) \077 0.55 : 1}, svg);\n"
    "        base += x;\n"
    "      });\n"
    "    }\n"
    "  }\n"
    "  /* hover: one column at a time */\n"
    "  const hl = el(\042rect\042, {x: 0, y: T, width: step, height: ph, fill: \042var(--ink)\042, opacity: 0}, svg);\n"
    "  const hit = el(\042rect\042, {x: L, y: T, width: pw, height: ph, fill: \042transparent\042}, svg);\n"
    "  const move = ev => {\n"
    "    const pt = ev.touches \077 ev.touches[0] : ev;\n"
    "    const box = svg.getBoundingClientRect();\n"
    "    const i = Math.min(n - 1, Math.max(0, Math.floor(((pt.clientX - box.left) * W / box.width - L) / step)));\n"
    "    hl.setAttribute(\042x\042, L + step * i); hl.setAttribute(\042opacity\042, 0.06);\n"
    "    let html = `<b>${labels[i]}</b>${opts.partial && opts.partial(i) \077 ' <span class=\042muted\042>(so far)</span>' : \042\042}`;\n"
    "    for (const s of series) html += `<br><i style=\042background:${s.color}\042></i>${s.name}: <b>${fmt(s.values[i])}</b>`;\n"
    "    if (kind === \042stack\042 && series.length > 1) html += `<br><span class=\042muted\042>total ${fmt(series.reduce((a, s) => a + (s.values[i] || 0), 0))}</span>`;\n"
    "    showTip(host, html, pt.clientX, pt.clientY);\n"
    "  };\n"
    "  hit.addEventListener(\042mousemove\042, move); hit.addEventListener(\042touchstart\042, move, {passive: true});\n"
    "  hit.addEventListener(\042mouseleave\042, () => { hl.setAttribute(\042opacity\042, 0); hideTip(); });\n"
    "}\n"
    "\n"
    "/* \342\224\200\342\224\200 the page \342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200\342\224\200 */\n"
    "function tile(k, val, sub) { return `<div class=\042tile\042><div class=\042v\042>${val}</div><div class=\042k\042>${k}${sub \077 `<br><span class=\042muted\042>${sub}</span>` : \042\042}</div></div>`; }\n"
    "function ago(t) { const s = Math.round(Date.now() / 1000 - t); return s < 90 \077 s + \042 s ago\042 : s < 5400 \077 Math.round(s / 60) + \042 min ago\042 : Math.round(s / 3600) + \042 h ago\042; }\n"
    "function renderNow() {\n"
    "  if (!now) return;\n"
    "  const n = now.now || {}, t = now.today || {};\n"
    "  const up = Math.max(0, Date.now() / 1000 - now.started);\n"
    "  const upS = up < 3600 \077 Math.round(up / 60) + \042 min\042 : up < 172800 \077 (up / 3600).toFixed(1) + \042 h\042 : (up / 86400).toFixed(1) + \042 days\042;\n"
    "  $(\042now\042).innerHTML =\n"
    "    tile(\042players online\042, fmt(n.players), fmt(n.sessions) + \042 connections\042) +\n"
    "    tile(\042games waiting\042, fmt(n.games_waiting)) +\n"
    "    tile(\042races under way\042, fmt(n.games_racing)) +\n"
    "    tile(\042private games\042, fmt(n.games_private)) +\n"
    "    tile(\042today: unique players\042, fmt(t.unique_players), fmt(t.signins) + \042 sign-ins\042) +\n"
    "    tile(\042today: peak online\042, fmt(t.peak_players)) +\n"
    "    tile(\042today: races started\042, fmt(t.games_started), fmt(t.race_results) + \042 results\042) +\n"
    "    tile(\042server up\042, upS, now.geo_ranges \077 \042country database loaded\042 : \042no country database\042);\n"
    "  $(\042upd\042).textContent = \042updated \042 + ago(now.updated) + \042 \302\267 \042 + new Date(now.updated * 1000).toLocaleString();\n"
    "}\n"
    "function render() {\n"
    "  const G = grouped(gran), labels = G.map(g => labelOf(g.key, gran));\n"
    "  const short = i => gran === \042day\042 \077 labelOf(G[i].key, \042day\042) : gran === \042week\042 \077 labelOf(G[i].key, \042day\042) : labelOf(G[i].key, \042month\042);\n"
    "  const partial = i => G[i].partial;\n"
    "  const sum = f => G.map(g => g.sum[f] || 0);\n"
    "  const all = days();\n"
    "  $(\042span\042).textContent = all.length \077 `${all[0].date} to ${all[all.length - 1].date}, ${all.length} day(s) with data` : \042\042;\n"
    "  $(\042playersNote\042).textContent = gran === \042day\042 \077 \042Unique players per day\042 :\n"
    "    `Unique players per day, added up over the ${gran} (player-days; the same person on two days counts twice)`;\n"
    "  chart($(\042cPlayers\042), labels, [{name: gran === \042day\042 \077 \042unique players\042 : \042player-days\042, color: S(1), values: sum(\042unique_players\042)}], \042bar\042, {short, partial, h: 210});\n"
    "  chart($(\042cPeak\042), labels, [{name: \042peak players\042, color: S(3), values: G.map(g => g.peak_players)}], \042bar\042, {short, partial});\n"
    "  chart($(\042cSignins\042), labels, [{name: \042sign-ins\042, color: S(7), values: sum(\042signins\042)}], \042bar\042, {short, partial});\n"
    "  chart($(\042cGames\042), labels, [\n"
    "    {name: \042created\042, color: S(1), values: sum(\042games_created\042)},\n"
    "    {name: \042started\042, color: S(2), values: sum(\042games_started\042)},\n"
    "    {name: \042race results\042, color: S(3), values: sum(\042race_results\042)}], \042line\042, {short, h: 210});\n"
    "  chart($(\042cModes\042), labels, MODES.map(([k, name], i) => ({name, color: S(i + 1), values: sum(\042started_\042 + k)})).filter(s => s.values.some(x => x)), \042stack\042, {short, partial});\n"
    "  chart($(\042cWaits\042), labels, [\n"
    "    {name: \042begun\042, color: S(1), values: sum(\042waits\042)},\n"
    "    {name: \042joined\042, color: S(3), values: sum(\042waits_joined\042)},\n"
    "    {name: \042race gone\042, color: S(2), values: sum(\042waits_gone\042)},\n"
    "    {name: \042raced again full\042, color: S(7), values: sum(\042waits_full\042)}], \042line\042, {short});\n"
    "  {\n"
    "    const tot = f => all.reduce((x, d) => x + v(d, f), 0);\n"
    "    $(\042tRelay\042).innerHTML = `<div class=\042tiles\042>` + tile(\042packets relayed\042, fmt(tot(\042relay_packets\042))) +\n"
    "      tile(\042MB relayed\042, (tot(\042relay_bytes\042) / 1048576).toFixed(1)) + tile(\042games relayed\042, fmt(tot(\042relay_games\042))) +\n"
    "      tile(\042dropped\042, fmt(tot(\042relay_dropped\042))) + `</div>`;\n"
    "    chart($(\042cRelay\042), labels, [\n"
    "      {name: \042packets relayed\042, color: S(1), values: sum(\042relay_packets\042)},\n"
    "      {name: \042dropped\042, color: S(2), values: sum(\042relay_dropped\042)}], \042line\042, {short});\n"
    "  }\n"
    "  const sizes = []; for (let p = 1; p <= 8; p++) sizes.push(all.reduce((a, d) => a + v(d, \042start_players_\042 + p), 0));\n"
    "  chart($(\042cSize\042), [\0421\042, \0422\042, \0423\042, \0424\042, \0425\042, \0426\042, \0427\042, \0428\042].map(x => x + \042 player\042 + (x === \0421\042 \077 \042\042 : \042s\042)),\n"
    "    [{name: \042races\042, color: S(4), values: sizes}], \042bar\042, {short: i => String(i + 1)});\n"
    "  /* modes, all time */\n"
    "  let mt = \042<tr><th>Mode</th><th>created</th><th>started</th><th>share</th></tr>\042;\n"
    "  const st = MODES.map(([k]) => all.reduce((a, d) => a + v(d, \042started_\042 + k), 0)), stAll = st.reduce((a, b) => a + b, 0);\n"
    "  MODES.forEach(([k, name], i) => {\n"
    "    const c = all.reduce((a, d) => a + v(d, \042created_\042 + k), 0);\n"
    "    mt += `<tr><td><i style=\042display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:6px;background:${S(i + 1)}\042></i>${name}</td><td>${fmt(c)}</td><td>${fmt(st[i])}</td><td>${stAll \077 (100 * st[i] / stAll).toFixed(1) + \042%\042 : \042\342\200\223\042}</td></tr>`;\n"
    "  });\n"
    "  $(\042tModes\042).innerHTML = `<table>${mt}</table>`;\n"
    "  renderCountries();\n"
    "  /* every day */\n"
    "  let dt = \042<tr><th>Date</th><th>unique</th><th>sign-ins</th><th>peak</th><th>created</th><th>started</th><th>results</th><th>waits</th><th>joined</th><th>refused</th></tr>\042;\n"
    "  for (const d of [...all].reverse())\n"
    "    dt += `<tr><td>${d.date}${d.partial \077 \042 (so far)\042 : \042\042}</td><td>${fmt(d.unique_players)}</td><td>${fmt(d.signins)}</td><td>${fmt(d.peak_players)}</td><td>${fmt(d.games_created)}</td><td>${fmt(d.games_started)}</td><td>${fmt(d.race_results)}</td><td>${fmt(d.waits)}</td><td>${fmt(d.waits_joined)}</td><td>${fmt(d.refused_full)}</td></tr>`;\n"
    "  $(\042tDays\042).innerHTML = dt;\n"
    "}\n"
    "function renderCountries() {\n"
    "  let all = days();\n"
    "  if (ccRange !== \042all\042) all = all.slice(-(+ccRange));\n"
    "  const agg = new Map();\n"
    "  for (const d of all) for (const [cc, [u, s]] of Object.entries(d.countries || {})) {\n"
    "    const a = agg.get(cc) || {cc, u: 0, s: 0}; a.u += u; a.s += s; agg.set(cc, a);\n"
    "  }\n"
    "  const rows = [...agg.values()].sort((a, b) => b.u - a.u || b.s - a.s || (a.cc < b.cc \077 -1 : 1));\n"
    "  const tu = rows.reduce((a, r) => a + r.u, 0), ts = rows.reduce((a, r) => a + r.s, 0);\n"
    "  const withCc = all.filter(d => d.countries && Object.keys(d.countries).length).length;\n"
    "  $(\042ccNote\042).textContent = `${rows.filter(r => r.cc !== \042\077\077\042).length} countries \302\267 ${all.length} day(s)` +\n"
    "    (withCc < all.length \077 ` (${all.length - withCc} from before countries were counted)` : \042\042);\n"
    "  const top = rows.slice(0, 15), m = top.length \077 top[0].u || 1 : 1;\n"
    "  $(\042ccTop\042).innerHTML = top.length \077 top.map(r =>\n"
    "    `<span>${flag(r.cc)} ${ccLabel(r.cc)}</span><div class=\042t\042 style=\042width:${(100 * r.u / m).toFixed(1)}%;background:${r.cc === \042\077\077\042 \077 \042var(--ink3)\042 : \042var(--s1)\042}\042></div><span class=\042n\042>${fmt(r.u)}</span>`).join(\042\042)\n"
    "    : '<span class=\042muted\042>No countries counted yet.</span>';\n"
    "  let t = \042<tr><th>Country</th><th>code</th><th>player-days</th><th>sign-ins</th><th>share</th></tr>\042;\n"
    "  for (const r of rows) t += `<tr><td>${flag(r.cc)} ${ccLabel(r.cc)}</td><td>${r.cc}</td><td>${fmt(r.u)}</td><td>${fmt(r.s)}</td><td>${tu \077 (100 * r.u / tu).toFixed(1) + \042%\042 : \042\342\200\223\042}</td></tr>`;\n"
    "  if (rows.length) t += `<tr><td><b>All</b></td><td></td><td><b>${fmt(tu)}</b></td><td><b>${fmt(ts)}</b></td><td></td></tr>`;\n"
    "  $(\042ccTable\042).innerHTML = t;\n"
    "}\n"
    "\n"
    "function setSeg(id, attr, val) { for (const b of $(id).querySelectorAll(\042button\042)) b.setAttribute(\042aria-pressed\042, b.dataset[attr] === val \077 \042true\042 : \042false\042); }\n"
    "$(\042gran\042).addEventListener(\042click\042, e => { const g = e.target.dataset && e.target.dataset.g; if (!g) return; gran = g; try { localStorage.setItem(\042td-gran\042, g); } catch (x) {} setSeg(\042gran\042, \042g\042, g); render(); });\n"
    "$(\042ccRange\042).addEventListener(\042click\042, e => { const r = e.target.dataset && e.target.dataset.r; if (!r) return; ccRange = r; setSeg(\042ccRange\042, \042r\042, r); renderCountries(); });\n"
    "$(\042theme\042).addEventListener(\042click\042, () => {\n"
    "  const dark = matchMedia(\042(prefers-color-scheme: dark)\042).matches;\n"
    "  const cur = document.documentElement.dataset.theme || (dark \077 \042dark\042 : \042light\042);\n"
    "  const next = cur === \042dark\042 \077 \042light\042 : \042dark\042;\n"
    "  document.documentElement.dataset.theme = next;\n"
    "  try { localStorage.setItem(\042td-theme\042, next); } catch (x) {}\n"
    "});\n"
    "try { const t = localStorage.getItem(\042td-theme\042); if (t) document.documentElement.dataset.theme = t; } catch (x) {}\n"
    "setSeg(\042gran\042, \042g\042, gran);\n"
    "let lastW = 0;\n"
    "addEventListener(\042resize\042, () => { if (Math.abs(innerWidth - lastW) > 40) { lastW = innerWidth; render(); } });\n"
    "\n"
    "async function loadNow() {\n"
    "  try { now = JSON.parse(await getText(\042now.json\042)); $(\042err\042).textContent = \042\042; }\n"
    "  catch (e) { $(\042err\042).textContent = \042Could not read now.json: \042 + e.message; }\n"
    "}\n"
    "async function loadHistory() {\n"
    "  try { history = parseLines(await getText(\042history.jsonl\042)); }\n"
    "  catch (e) { $(\042err\042).textContent = \042Could not read history.jsonl: \042 + e.message; }\n"
    "}\n"
    "(async () => {\n"
    "  await Promise.all([loadNow(), loadHistory()]);\n"
    "  lastW = innerWidth;\n"
    "  renderNow(); render();\n"
    "  let lastDate = now && now.today && now.today.date;\n"
    "  setInterval(async () => {\n"
    "    await loadNow();\n"
    "    const d = now && now.today && now.today.date;\n"
    "    if (d !== lastDate) { lastDate = d; await loadHistory(); }   /* midnight: a new finished day */\n"
    "    renderNow(); render();\n"
    "  }, 30000);\n"
    "})();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n";
#endif
